2.  **`feature_store_manager.c` Core Logic:** A new internal struct is defined, and `fsm_get_feature_vector` contains the core logic.
    ```c
    // Internal struct for the doubly-linked list node
    typedef struct CacheEntry {
        char* key;
        FeatureVector* value;
        size_t size_bytes;
        struct CacheEntry *prev;
        struct CacheEntry *next;
    } CacheEntry;

    // In fsm_get_feature_vector(...)
    if (!manager->cache_enabled) {
        return _fsm_read_from_disk(manager, key);
    }

    CacheEntry* entry = (CacheEntry*)ll_hashmap_get(manager->cache_map, key);
    if (entry != NULL) {
        // Cache HIT
        ll_log_debug("Feature Store Cache HIT for key '%s'", key);
        _fsm_move_to_front(manager, entry);
        return entry->value;
    } else {
        // Cache MISS
        ll_log_debug("Feature Store Cache MISS for key '%s'", key);
        FeatureVector* vector = _fsm_read_from_disk(manager, key);
        if (vector != NULL) {
            _fsm_cache_add(manager, key, vector);
        }
        return vector;
    }
    ```

3.  **`feature_store_manager.c` Eviction Logic:** The `_fsm_cache_add` function must contain the eviction check.
    ```c
    // In _fsm_cache_add(...)
    // ... after adding new entry ...
    while (manager->current_cache_size_bytes > manager->max_cache_size_bytes) {
        _fsm_evict_lru(manager);
    }
    ```

